from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-N02"><div class="chap"><div class="chap-head"><div class="code">N02 · N-07-Néphrologie</div><h1>Hématurie récidivante et persistante</h1><span class="status">Monographie pédagogique · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#n02-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="N02">'''
a+=sec('question','Des urines anormales, une personne qui se sent bien', '''<p><b>Vignette fictive.</b> Une jeune adulte consulte après trois examens urinaires positifs pour le sang en six mois. Elle n’a ni brûlure, ni douleur, ni sang visible. Sa mère rapporte les mêmes résultats depuis longtemps. La pression artérielle et la créatinine sont normales ; le rapport albumine/créatinine n’a pas encore été mesuré. Faut-il rassurer définitivement, demander un scanner ou prescrire un corticoïde ?</p><p>Aucune de ces décisions ne découle de la seule bandelette. Il faut confirmer les hématies, examiner leur morphologie, mesurer l’albuminurie, reconstituer l’histoire familiale et rechercher les signaux de gravité. Une atteinte liée au collagène IV est possible, mais une histoire familiale ne prouve pas son mécanisme. Le bilan doit donner une explication et un plan de suivi proportionné, sans transformer une anomalie isolée en maladie rapidement progressive.</p>'''+key('Confirmer le sang, localiser son origine, apprécier le risque, puis choisir les examens utiles.'),('CH-HUG-DEF','CH-HUG-ORIENT','EU-ALPORT-GEN'))
a+=sec(1,'1. Définition : un phénotype, plusieurs maladies', '''<p>L’hématurie correspond à la présence d’érythrocytes dans l’urine. Elle est macroscopique si le sang est visible et microscopique s’il est détecté par analyse. La bandelette réagit aussi à l’hémoglobine et à la myoglobine : une réaction positive n’est donc pas, à elle seule, la preuve d’érythrocytes urinaires. Le résultat se confirme par une mesure cellulaire et, lorsque l’origine rénale est discutée, par l’examen du sédiment.</p><p><b>Récidivante</b> décrit des épisodes séparés ; <b>persistante</b> décrit une anomalie retrouvée sur plusieurs prélèvements. Les définitions temporelles varient selon le contexte. Le guide européen Alport utilise au moins deux prélèvements sur six à douze mois ; l’approche européenne pédiatrique recherche la persistance sur trois à cinq examens en trois à six mois. Ces durées organisent l’évaluation d’une personne stable : elles ne justifient jamais d’attendre devant une insuffisance rénale, une protéinurie importante ou des signes systémiques.</p><p>Une hématurie est dite <b>isolée</b> lorsque ne s’y associent ni protéinurie/albuminurie pathologique, ni hypertension, ni altération de la fonction rénale, ni manifestation systémique évocatrice. Cette qualification nécessite de mesurer ces paramètres ; « sans douleur » ne signifie pas « isolée ». Le présent cours traite surtout le phénotype glomérulaire récurrent ou persistant, ses causes IgA et collagène IV, et les exclusions urologiques nécessaires.</p><p>La catégorie administrative N02 ne doit être attribuée qu’après le raisonnement clinique. Dans la CIM-10-GM suisse consultée, elle exclut l’hématurie sans autre indication R31 et le syndrome douleur lombaire–hématurie N39.81. Les sous-catégories morphologiques ne se déduisent pas d’une bandelette : les qualificatifs .0 à .8 reposent normalement sur une preuve histologique. Le mot historique « bénigne » conservé dans certains libellés n’est pas une garantie pronostique.</p>''',('CH-HUG-DEF','EU-YOUNG','EU-ALPORT-GEN','CH-CIM'))
a+=sec(2,'2. Épidémiologie et populations à risque', '''<p>La fréquence observée de la microhématurie dépend du seuil utilisé, de l’âge, du dépistage, du nombre de prélèvements et des causes transitoires exclues. Les séries de population, de consultations et de biopsies ne mesurent pas le même phénomène. Les sources retenues ne fournissent pas une incidence suisse fiable de la catégorie clinique N02 : aucun chiffre national n’est extrapolé à partir d’une cohorte étrangère.</p><p>Chez les enfants et les jeunes adultes ayant une microhématurie glomérulaire persistante, les maladies liées à COL4A3, COL4A4 ou COL4A5 et la néphropathie à IgA occupent une place importante dans le diagnostic différentiel. Une variante hétérozygote de COL4A3 ou COL4A4 peut être fréquente dans la population, mais sa présence ne signifie pas que toute personne développera une insuffisance rénale. Les familles adressées en centre spécialisé enrichissent les séries en phénotypes sévères.</p><p>Chez l’adulte plus âgé, le tabac, l’antécédent d’hématurie visible, certaines expositions professionnelles, une irradiation pelvienne ou le cyclophosphamide augmentent le poids d’une cause urothéliale. Une origine glomérulaire probable ne rend pas cette seconde hypothèse impossible. L’évaluation combine la probabilité de maladie rénale et le risque urologique au lieu d’appliquer le même scanner à tous les âges.</p><p>Le contexte familial change la démarche : insuffisance rénale inexpliquée, dialyse, surdité ou anomalies oculaires chez des apparentés orientent vers le collagène IV. L’absence de ces signes ne l’exclut pas, en raison d’une expression variable et de manifestations parfois tardives. L’histoire doit donc préciser les âges et les diagnostics, pas seulement recueillir « maladie rénale dans la famille ».</p>''',('CH-HUG-URO','EU-YOUNG','EU-ALPORT-GEN','EU-ALPORT-RISK'))
a+=sec(3,'3. Physiopathologie : du filtre au signe urinaire', '''<p>Le filtre glomérulaire associe endothélium capillaire, membrane basale et podocytes. Une atteinte de ce dispositif peut laisser passer des érythrocytes et des protéines dans l’espace urinaire. La morphologie érythrocytaire se modifie au cours de ce passage et du trajet urinaire ; des acanthocytes ou des cylindres érythrocytaires orientent vers une origine glomérulaire. Leur absence dans un prélèvement ne suffit pas à exclure cette origine.</p><p>Dans les maladies liées au collagène IV, une anomalie génétique altère une composante structurale de la membrane basale glomérulaire. Selon le génotype et le stade, l’aspect peut être aminci, irrégulier ou lamellé. Le défaut structural explique l’hématurie précoce ; l’apparition d’albuminurie, la perte podocytaire et les lésions secondaires de sclérose annoncent un risque plus important. Une lésion de sclérose segmentaire secondaire ne transforme pas cette maladie en indication automatique d’immunosuppression.</p><p>Dans la néphropathie à IgA, les dépôts glomérulaires d’IgA définissent une maladie immunologique dont la démonstration nécessite une biopsie. Des épisodes visibles proches d’une infection respiratoire sont évocateurs, mais ne constituent pas un test diagnostique. Le risque évolutif se lit surtout dans la protéinurie et la trajectoire du débit de filtration, avec les données histologiques et cliniques.</p><p>Un saignement issu des voies excrétrices rejoint l’urine après le filtre. Calcul, infection, tumeur ou autre lésion peuvent donc donner une hématurie sans anomalie primitive de la membrane basale. La distinction physiopathologique guide le choix entre analyse glomérulaire, génétique, biopsie et exploration urologique ; elle n’autorise pas à négliger une cause concomitante.</p>'''+figure('podocytes'),('NORMAL-FILTRE','CH-HUG-ORIENT','EU-ALPORT-RISK','INT-IGA-DX'))
a+=sec(4,'4. Démarche clinique : décider du délai avant de multiplier les tests', '''<p><b>Première étape : rechercher une complication.</b> Une baisse rapide de fonction rénale, une oligurie, une dyspnée avec suspicion de surcharge ou d’hémorragie pulmonaire, une hypertension sévère avec retentissement, ou un saignement visible mal toléré imposent une évaluation urgente. Des caillots avec impossibilité d’uriner font rechercher une rétention. Ces tableaux sortent de la surveillance d’une microhématurie isolée.</p><p><b>Deuxième étape : valider le prélèvement.</b> Vérifier règles, contamination génitale, infection, exercice intense récent, traumatisme, couleur des urines et médicaments. Une cause transitoire plausible se traite ou disparaît puis le contrôle est organisé ; l’anomalie persistante ne doit pas rester attribuée indéfiniment à cet épisode. Sous anticoagulant, rechercher la source du saignement au lieu d’en faire une explication suffisante.</p><p><b>Troisième étape : établir le profil.</b> Mesurer pression artérielle, créatinine avec débit estimé, albuminurie et/ou protéinurie quantitatives ; examiner le sédiment. La stratégie HUG propose de confirmer une origine glomérulaire sur un second prélèvement à plus d’une semaine chez la personne stable, puis un avis néphrologique. Albuminurie, hypertension, baisse du débit ou manifestations systémiques renforcent le besoin d’évaluation ; la vitesse de dégradation détermine l’urgence.</p><p><b>Quatrième étape : choisir une filière.</b> Chez le jeune sans signe de gravité, histoire familiale, échographie et génétique peuvent précéder une biopsie. Une présentation active avec protéinurie ou insuffisance rénale nécessite un bilan néphrologique plus rapide. Chez l’adulte à risque urothélial, intégrer l’urologie même si des indices glomérulaires sont présents. Expliquer au patient ce qui est établi, ce qui reste hypothétique et la date du prochain contrôle.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT','CH-HUG-URO','EU-YOUNG','EU-HEMAT'))
a+=sec(5,'5. Anamnèse analytique',table(['Domaine','Questions utiles','Ce que la réponse change'],[['Chronologie','Premier résultat, nombre de contrôles, épisodes visibles, intervalle avec infection ou effort','Distinguer transitoire, récurrent et persistant ; rapprocher les résultats de la fonction rénale.'],['Saignement','Couleur, caillots, moment dans la miction, douleur, règles ou saignement génital','Confirmer l’origine urinaire ; les caillots orientent vers une source urologique.'],['Voies urinaires','Brûlures, pollakiurie, fièvre, colique, traumatisme, geste récent','Chercher infection, calcul ou lésion ; recontrôler après résolution.'],['Retentissement rénal','Œdèmes, baisse du volume urinaire, pression connue, créatinine antérieure','Repérer un syndrome néphritique et la trajectoire.'],['Manifestations systémiques','Purpura, arthralgies, symptômes respiratoires, atteinte générale','Discuter vascularite, lupus ou autre maladie systémique ; urgence si atteinte d’organe.'],['Famille','Hématurie, insuffisance rénale, âge de dialyse, audition, yeux, consanguinité','Établir un arbre familial et orienter COL4A3/4/5.'],['Expositions','Tabac quantifié, irradiation pelvienne, cyclophosphamide, produits professionnels, voyages pertinents','Estimer le risque urologique et les diagnostics spécifiques.'],['Traitements et projet de grossesse','Anticoagulants, anti-inflammatoires, bloqueurs du système rénine–angiotensine, compléments','Évaluer effets indésirables, interactions et traitements à adapter.']])+'''<p>Un épisode d’urines foncées pendant une infection peut orienter vers une néphropathie à IgA ; il ne prouve ni l’IgA ni une maladie postinfectieuse. Demander les comptes rendus antérieurs et leurs dates est plus utile que retenir un délai approximatif reconstruit plusieurs années après. Une maladie familiale dite « bénigne » mérite une reformulation prudente lorsque l’on découvre une albuminurie ou une baisse de fonction.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT','CH-HUG-URO','EU-ALPORT-GEN','EU-HEMAT'))
a+=sec(6,'6. Examen clinique : chercher le retentissement et les indices extrarénaux', '''<p>Mesurer la pression dans des conditions adaptées, rechercher les valeurs antérieures et répéter une mesure inattendue. Chez l’enfant, interpréter avec les références pédiatriques ; le seuil et l’objectif d’un adulte ne se transposent pas. Évaluer poids, œdèmes, état d’hydratation et signes de surcharge. Une pression normale et l’absence d’œdèmes n’excluent pas une atteinte glomérulaire débutante.</p><p>Examiner abdomen et régions lombaires selon les symptômes ; une douleur, une masse ou une rétention orientent mais ne remplacent pas l’imagerie. Inspecter la peau lorsqu’un purpura ou une maladie systémique est évoqué, rechercher les signes articulaires et respiratoires associés. Une dyspnée, une désaturation ou une altération générale imposent de sortir du simple bilan ambulatoire.</p><p>Dans un contexte de collagène IV, rechercher les plaintes auditives et visuelles, puis organiser les examens spécialisés selon génotype et âge. Un entretien sans plainte auditive n’équivaut pas à une audiométrie normale. L’examen ophtalmologique de référence et son suivi sont adaptés au risque ; les porteurs hétérozygotes COL4A3/4 n’ont pas le même calendrier que les garçons avec forme liée à l’X ou les formes récessives.</p><p>Conclure l’examen par une synthèse : état stable ou instable, signes de rétention/surcharge, pression, manifestations extrarénales et limites de l’examen. Une consultation clinique rassurante n’annule pas une albuminurie quantitative ou une créatinine qui augmente.</p>''',('CH-HUG-ORIENT','CH-HUG-URO','EU-ALPORT-SUIVI','EU-YOUNG'))
a+=sec(7,'7. Syndromes et classifications utiles',table(['Profil','Éléments','Décision structurante'],[['Microhématurie glomérulaire isolée','Persistance confirmée, sans albuminurie/protéinurie, hypertension ni baisse du débit','Avis néphrologique, histoire familiale, échographie ; génétique selon contexte ; suivi.'],['Hématurie avec albuminurie ou protéinurie','Atteinte de filtration plus étendue ; risque évolutif supérieur selon cause','Quantifier, suivre et discuter biopsie ou génétique ; néphroprotection adaptée.'],['Syndrome néphritique','Hématurie avec retentissement rénal, pression/œdèmes et parfois baisse rapide du débit','Évaluation accélérée ou urgente, bilan étiologique et biopsie selon tableau.'],['Épisodes macroscopiques récurrents','Infections associées possibles, douleur/caillots ou non','Confirmer l’origine ; IgA n’est qu’une hypothèse avant biopsie ; surveiller fonction.'],['Phénotype collagène IV','Famille, hématurie persistante, audition/yeux ou anomalie génétique','Distinguer lié à X, autosomique récessif et hétérozygotie ; conseil familial.'],['Profil urologique','Hématies plutôt non glomérulaires, caillots, symptômes ou facteurs de risque','Échographie, cystoscopie et/ou imagerie en coupe selon risque et âge.']])+'''<p>La classification génétique Alport distingue COL4A5 lié à l’X, variants bialléliques COL4A3/4 et variants hétérozygotes COL4A3/4. Les risques et le moment de début du traitement ne sont pas identiques. Dans l’IgA biopsiée, MEST-C décrit des lésions histologiques ; ce n’est ni un score clinique de bandelette ni un déclencheur autonome de corticoïdes. Les cylindres ou un croissant isolé ne suffisent pas non plus à définir une progression rapide.</p>''',('EU-ALPORT-GEN','EU-ALPORT-RISK','INT-IGA-DX','INT-IGA-SPECIAL','CH-HUG-ORIENT','CH-HUG-URO'))
save('a',a)
b=sec(8,'8. Diagnostic positif : distinguer le signe et sa cause', '''<p>La première preuve est la présence d’érythrocytes dans un échantillon correctement recueilli. Les seuils ne sont pas universels : les HUG retiennent un seuil physiologique local de 26 millions/L, soit 26/µL, approximativement cinq hématies par champ ; le manuel français CUEN emploie au moins 10/µL. Le nombre par champ dépend de la préparation et de la méthode. Utiliser la référence du laboratoire et écrire l’unité évite de transformer une divergence technique en contradiction clinique.</p><p>L’origine glomérulaire est soutenue par des hématies dysmorphiques, particulièrement des acanthocytes, et des cylindres érythrocytaires. La stratégie HUG cite plus de 60 % de dysmorphie ou plus de 5 % d’acanthocytes ; la recommandation européenne pour jeunes utilise également le repère d’environ 5 % d’acanthocytes. Ces résultats dépendent de l’expertise et du prélèvement : un sédiment peu contributif ne ferme pas le dossier si les autres indices persistent.</p><p>La cause nécessite une preuve distincte. <b>L’IgA est un diagnostic de biopsie</b> : le dosage sanguin d’IgA ne le remplace pas. Chez l’adulte, KDIGO 2025 propose de considérer la biopsie lorsqu’une IgA est possible et que la protéinurie atteint au moins 0,5 g/j, si le geste est réalisable. Une suspicion de collagène IV conduit à une analyse adaptée des trois gènes ; une variante de signification incertaine ne suffit pas à établir un diagnostic moléculaire.</p><p>Un résultat génétique doit être confronté au phénotype et à la famille. Une variante hétérozygote COL4A3/4 peut ne pas expliquer une évolution inhabituellement sévère ; une maladie surajoutée est possible. Inversement, un panel négatif ne rend pas toute maladie génétique impossible. La biopsie peut être utile devant une évolution atypique, une insuffisance aiguë ou un syndrome néphrotique inattendu.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT','EU-HEMAT','EU-YOUNG','EU-ALPORT-GEN','EU-ALPORT-RISK','INT-IGA-DX'))
b+=sec(9,'9. Explorations : une question avant chaque prescription', '''<p>Le bilan initial associe confirmation urinaire, sédiment, quantification de l’albuminurie/protéinurie, créatinine et estimation du débit, pression artérielle et échographie selon le contexte. Les HUG proposent notamment numération, électrolytes, albumine et marqueurs orientés par la présentation. Un panel immunologique large n’est pas un réflexe nécessaire pour toute hématurie isolée ; il devient pertinent si le tableau suggère une maladie systémique ou une glomérulonéphrite active.</p><p>Le rapport albumine/créatinine mesure la composante albuminurique ; le rapport protéines/créatinine mesure les protéines totales. Ils ne sont pas interchangeables. Un prélèvement du matin facilite l’interprétation chez le jeune et aide à examiner une composante orthostatique. Une hématurie visible peut augmenter la protéinurie mesurée par apport de sang : recontrôler sur urines claires pour apprécier la protéinurie rénale persistante, sans différer la prise en charge d’un tableau grave.</p><p>L’échographie explore rein, voies excrétrices et vessie sans irradiation. Chez l’enfant ou le jeune avec microhématurie isolée, elle est la première imagerie ; scanner et cystoscopie systématiques sont inappropriés. Chez l’adulte à risque urothélial, l’échographie ne remplace pas toujours la cystoscopie ou l’imagerie multiphasique. Les indications de contraste dépendent de la question, de la fonction rénale, de la grossesse et des contre-indications propres à chaque technique.</p><p>Biopsie et génétique répondent à des questions différentes. Le tissu décrit activité, chronicité et dépôts ; la génétique peut établir une maladie héréditaire, organiser le conseil familial et éviter certaines biopsies. Le choix dépend de la probabilité, de l’urgence, de la présentation et de l’impact attendu sur la conduite. Une variante découverte n’efface pas un signe discordant qui exige une autre investigation.</p>'''+figure('sediment'),('CH-HUG-ORIENT','CH-HUG-URO','EU-YOUNG','EU-HEMAT','EU-ALPORT-GEN','INT-IGA-DX'))
b+=sec(10,'10. Arbre diagnostique et diagnostics différentiels', '''<ol><li><b>Bandelette positive :</b> confirmer les hématies ; si elles manquent, envisager hémoglobinurie, myoglobinurie ou interférence, selon clinique et prélèvement.</li><li><b>Cause transitoire plausible :</b> infection, contamination menstruelle, effort ou geste ; traiter/écarter puis programmer un contrôle. Une persistance rouvre l’évaluation.</li><li><b>Gravité présente :</b> baisse rapide du débit, oligurie, signes systémiques, surcharge, saignement mal toléré ou rétention → évaluation urgente adaptée, sans délai de confirmation prolongé.</li><li><b>Indices glomérulaires :</b> sédiment, albuminurie, pression et fonction ; avis néphrologique. Famille/jeune isolé → collagène IV et stratégie génétique ; protéinurie ou activité → discuter biopsie, IgA et maladies inflammatoires.</li><li><b>Indices urologiques ou risque tumoral :</b> explorer selon âge et risque. Une hématurie sous anticoagulant et une anomalie rénale concomitante n’excluent pas une lésion urothéliale.</li><li><b>Bilan initial non concluant :</b> suivi daté, réévaluation de la persistance et des nouveaux signes ; ne pas conclure à une bénignité permanente.</li></ol>'''+table(['Hypothèse','Arguments','Limite décisive'],[['IgA','Épisodes proches d’infections, protéinurie, hématurie glomérulaire','Biopsie nécessaire ; IgA sanguine et chronologie ne prouvent pas.'],['Collagène IV','Famille, persistance jeune, audition/yeux, membrane basale anormale','Triade souvent incomplète ; variant incertain non diagnostique.'],['GN systémique ou rapidement progressive','Créatinine en hausse, protéinurie, manifestations extrarénales','Le traitement urgent dépend de la cause ; ne pas rester dans N02 isolé.'],['Infection, calcul, tumeur','Symptômes urinaires, colique, caillots ou facteurs de risque','Une absence de douleur ne rassure pas contre une tumeur.'],['Pigment sans hématies','Bandelette positive, absence d’érythrocytes confirmée','Chercher hémoglobine/myoglobine et contexte ; une urine rouge peut aussi être non hémique.']]),('CH-HUG-DEF','CH-HUG-ORIENT','CH-HUG-URO','EU-HEMAT','EU-ALPORT-GEN','INT-IGA-DX'))
b+=sec(11,'11. Prise en charge : traiter le risque démontré', '''<p><b>Hématurie isolée.</b> Il n’existe pas de prescription anti-inflammatoire ou immunosuppressive justifiée par la seule présence d’hématies. Expliquer le résultat, documenter une base de pression/fonction/protéines et organiser le suivi. Traiter une infection ou un calcul lorsqu’ils sont établis ; rechercher une lésion urologique selon risque. Les mesures générales incluent arrêt du tabac et contrôle des facteurs rénaux et cardiovasculaires pertinents.</p><p><b>Maladie du collagène IV.</b> Le blocage du système rénine–angiotensine est la base de néphroprotection. ERKNet/ERA/ESPN recommande de le débuter et titrer à la dose maximale tolérée dès la microalbuminurie, quel que soit le sous-type. Chez les garçons/mâles avec forme liée à l’X et dans les formes autosomiques récessives, un début après deux ans peut être proposé dès l’hématurie. En revanche, chez les femmes avec forme liée à l’X et les hétérozygotes COL4A3/4, l’hématurie isolée seule ne justifie pas ce début précoce. Ces distinctions empêchent de prescrire le même traitement à toute famille.</p><p>Les schémas pédiatriques européens et les indications Alport sont distincts des autorisations et doses des produits suisses. Le ramipril pédiatrique proposé dans le guide est hors indication suisse du produit relu ; le suivi spécialisé surveille pression, fonction rénale et potassium. Un inhibiteur SGLT2 peut être discuté chez certains adultes avec maladie rénale et albuminurie persistante, sur preuves limitées dans Alport ; il ne se transpose ni à l’enfant ni à une microhématurie isolée avec fonction normale.</p><p><b>IgA confirmée.</b> KDIGO 2025 vise une protéinurie inférieure à 0,5 g/j, idéalement inférieure à 0,3 g/j, et la préservation du débit. Les mesures de mode de vie comprennent apport sodé inférieur à 2 g/j de sodium, soit environ 5 g de sel, activité et contrôle pondéral adaptés, arrêt du tabac. Le blocage rénine–angiotensine est utilisé à dose tolérée sauf contre-indication. La cible tensionnelle adulte proposée ≤120/70 mmHg exige une mesure fiable et une tolérance clinique ; elle n’est pas une cible pédiatrique universelle.</p><p>Chez les personnes à risque de progression, des traitements visant la production d’IgA pathogène ou les conséquences de l’atteinte néphronique peuvent être discutés. La prescription suisse doit respecter les FI exactes : Kinpeygo est un budésonide à libération modifiée propre à l’IgA ; Filspari est le sparsentan, qui remplace le blocage rénine–angiotensine usuel et ne s’y ajoute pas. Forxiga a une indication de maladie rénale chronique, mais sa FI déconseille l’utilisation chez les patients recevant des immunosuppresseurs : une recommandation générale de combinaison ne gomme pas cette limite suisse.</p><p><b>Formes particulières.</b> Une insuffisance aiguë pendant une hématurie macroscopique nécessite soutien et réévaluation ; KDIGO propose de considérer une nouvelle biopsie si la fonction ne s’améliore pas dans les deux semaines après disparition du sang visible. Une IgA rapidement progressive, définie dans ce cadre par une chute d’au moins 50 % du débit en trois mois au plus après exclusions, exige biopsie et traitement spécialisé ; des croissants seuls ne suffisent pas à ce diagnostic. Les corticoïdes systémiques et cytotoxiques ne sont pas un traitement empirique de N02.</p>''',('CH-HUG-ORIENT','CH-HUG-URO','EU-ALPORT-TX','INT-IGA-TX','INT-IGA-SPECIAL','FI-RAMIPRIL','FI-FILSPARI','FI-KINPEYGO','FI-FORXIGA'))
b+=sec(12,'12. Prévention, suivi et pronostic', '''<p>Le suivi surveille une trajectoire, pas seulement la disparition du sang. Documenter pression, albuminurie/protéinurie, créatinine/débit, épisodes visibles, symptômes extrarénaux et tolérance thérapeutique. Une augmentation des protéines, une hypertension nouvelle ou une baisse de fonction change la catégorie de risque et le rythme des consultations. Le patient doit savoir qui contacter et quels signes imposent une consultation anticipée.</p><p>Pour les adultes asymptomatiques hétérozygotes COL4A3/4, le guide européen suggère un dépistage urinaire tous les un à deux ans et une pression au moins annuelle, adapté à l’histoire familiale. Lorsque l’albuminurie dépasse 30 mg/g sur deux prélèvements et qu’un traitement rénine–angiotensine est instauré, le débit et l’albuminurie sont suivis en général tous les six à douze mois, plus souvent selon stade et évolution. Ce calendrier de maladie stable n’est pas celui des contrôles de sécurité juste après une introduction ou une augmentation de médicament.</p><p>L’audition est surveillée plus étroitement dans les formes liées à l’X chez le garçon et les formes récessives : le guide propose un début vers quatre ans, annuel durant l’enfance puis espacé chez l’adulte. Les femmes liées à l’X et les hétérozygotes COL4A3/4 ont des besoins différents ; pour ces derniers, l’examen auditif est surtout guidé par les symptômes. L’ophtalmologie de référence et les contrôles sont individualisés. Le conseil génétique aborde transmission, apparentés, reproduction et implications d’un éventuel don de rein ; un apparenté porteur n’est pas présumé donneur sans risque.</p><p>Dans l’IgA, protéinurie et débit sont les repères pronostiques centraux. L’outil international de prédiction après biopsie estime un risque de déclin fonctionnel ou d’insuffisance rénale ; il ne calcule pas le bénéfice individuel d’un médicament et n’est pas validé pour une hématurie sans biopsie. Dans les maladies du collagène IV, le génotype, le sexe dans les formes liées à l’X, l’albuminurie et la trajectoire familiale modulent le risque. Le terme « familial bénin » doit être abandonné comme promesse définitive.</p><p>Après un bilan urologique négatif chez l’adulte, les HUG proposent un contrôle urinaire à douze mois, ou six mois dans certaines situations à faible risque explorées par échographie seule. L’arrêt éventuel de ce suivi est conditionnel ; hématurie persistante/récidivante, nouvel épisode visible ou nouveaux symptômes justifient une nouvelle discussion. Cela ne remplace pas le suivi d’une maladie glomérulaire confirmée.</p>''',('EU-ALPORT-SUIVI','EU-ALPORT-RISK','INT-IGA-DX','CH-HUG-URO'))
b+=sec(13,'13. Points clés et entraînement clinique', '''<ul><li>La bandelette détecte l’hème ; la présence de globules rouges doit être confirmée.</li><li>« Isolée » suppose pression, fonction et protéines évaluées, pas seulement absence de douleur.</li><li>Le sédiment oriente le compartiment ; il ne nomme pas seul l’étiologie.</li><li>IgA nécessite une biopsie ; collagène IV demande une interprétation génétique et clinique.</li><li>Une fonction qui baisse ou un syndrome systémique interdit d’attendre plusieurs mois.</li><li>Les calendriers, seuils et doses dépendent de l’âge, du génotype, de la méthode et du produit.</li></ul><p>Les exercices ci-dessous sont originaux et fictifs. Le rapprochement pédagogique avec PROFILES 2017 concerne notamment l’hématurie (SSP64), les anomalies histologiques/génétiques (SSP159), la fonction rénale (SSP161), le sédiment urinaire (SSP164) et la protéinurie (SSP173). Les exigences MEBEKO lues concernent l’examen 2026. Il ne s’agit ni d’un mapping officiel CIM–PROFILES ni de questions fédérales reproduites.</p>'''+''.join('<p>'+w('cas-'+str(i),'Cas clinique '+str(i)+' — raisonner avant de traiter')+'</p>' for i in range(1,5)),('CH-PROFILES','CH-MEBEKO','CH-HUG-DEF','EU-ALPORT-GEN','INT-IGA-DX'))
b+=sec(14,'14. Pièges à éviter',table(['Raccourci trompeur','Correction'],[['Bandelette positive = hématurie glomérulaire','Confirmer les cellules puis rechercher les indices d’origine.'],['Urines rouges = gravité proportionnelle à la couleur','Évaluer tolérance, rétention et fonction ; la couleur ne quantifie pas le risque.'],['Anticoagulant = cause suffisante','Le traitement peut révéler un saignement ; rechercher sa source.'],['Hématurie familiale = bénigne','Mesurer protéines et fonction, discuter collagène IV et suivi.'],['IgA sérique élevée = IgA rénale','La biopsie établit le diagnostic ; les causes secondaires sont recherchées.'],['Panel génétique négatif = aucun risque héréditaire','Sensibilité et interprétation ont des limites ; réexaminer le phénotype.'],['Tout croissant = progression rapide','L’évolution fonctionnelle et les exclusions sont nécessaires.'],['Plus de médicaments = meilleure néphroprotection','Éviter double blocage ; respecter interactions et FI, notamment immunosuppression/SGLT2.'],['Budésonide = aucun effet systémique','Surveiller infection, axe surrénalien et effets glucocorticoïdes.'],['Un seuil français, suisse ou pédiatrique vaut partout','Citer population, laboratoire, unité et source.']])+key('Une surveillance explicite est une prise en charge ; une absence de plan ne l’est pas.'),('CH-HUG-DEF','CH-HUG-ORIENT','CH-HUG-URO','EU-ALPORT-GEN','EU-ALPORT-RISK','INT-IGA-DX','INT-IGA-SPECIAL','FI-KINPEYGO','FI-FORXIGA'))
b+='</div></div>';save('b',b)
print('N02 : 14 sections cliniques écrites ; relecture encore requise')
